#!/usr/bin/env node
// Writes docs/guidelines/rules-index.md and enforcement.md from the rule sources, the checks'
// *.rules.json, tool-enforcement.json and enforcement-notes.json. `--check` fails when either is stale.
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

import { INTRO_FILE, readDeclarations, readNotes, readSources, readTools } from './lib/guidelines.mjs'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const HEADER =
  '<!-- Generated by `node scripts/generate-guidelines.mjs` from the rule files, the checks, tool-enforcement.json and enforcement-notes.json. Do not edit: change those and run it. -->'
const REVIEW = 'review'

/** A Markdown table; `|` inside a cell is escaped. */
function renderTable(header, rows) {
  const line = (cells) => `| ${cells.map((cell) => cell.replaceAll('|', '\\|')).join(' | ')} |`
  return [line(header), line(header.map(() => '---')), ...rows.map(line)].join('\n')
}

/** Rule id → the sorted, de-duplicated names of what enforces it. */
function groupChecks(declarations) {
  const byId = new Map()
  for (const { id, check } of declarations) byId.set(id, [...new Set([...(byId.get(id) ?? []), check])].sort())
  return byId
}

/** One row per rule: id, what enforces it (or `review`), and its note. */
function ruleRows(definitions, checksById, notes) {
  return definitions.map(({ id }) => [id, (checksById.get(id) ?? []).join(', ') || REVIEW, notes.get(id)?.note ?? ''])
}

/** rules-index.md: every id, the file that defines it, and what enforces it. */
function renderIndex({ sources, declarations }) {
  const checksById = groupChecks(declarations)
  const rows = sources.flatMap(({ file, definitions }) =>
    definitions.map(({ id }) => [id, `\`${file}\``, (checksById.get(id) ?? []).join(', ') || REVIEW]),
  )
  const checked = rows.filter((row) => row[2] !== REVIEW).length
  return `${HEADER}

# Rules index

Every rule id, the file that defines it, and what enforces it. ${rows.length} rules: ${checked} enforced
by a check or tool, in whole or in part, and ${rows.length - checked} by review only.
[enforcement.md](./enforcement.md) says what each check covers and why a rule is review.

${renderTable(['Rule', 'Defined in', 'Enforced by'], rows)}
`
}

/** enforcement.md: the hand-written intro, the tools, then one table per rule file. */
function renderEnforcement({ intro, sources, declarations, notes, tools }) {
  const checksById = groupChecks(declarations)
  const toolRows = Object.entries(tools).map(([tool, { runsIn, rules }]) => [
    tool,
    runsIn,
    Object.entries(rules)
      .map(([rule, ids]) => `\`${rule}\` (${ids.join(', ')})`)
      .join(', '),
  ])
  const sections = sources
    .filter(({ definitions }) => definitions.length > 0)
    .map(
      ({ file, title, definitions }) =>
        `## ${title} (\`${file}\`)\n\n${renderTable(['Rule', 'Enforced by', 'Note'], ruleRows(definitions, checksById, notes))}`,
    )
  return `${HEADER}

${intro.trim()}

## Outside tools

${renderTable(['Tool', 'Runs in', 'Rules it enforces'], toolRows)}

${sections.join('\n\n')}
`
}

/** Every generated file and its content. */
function renderAll(root) {
  const sources = readSources(root)
  const declarations = readDeclarations(root)
  const intro = readFileSync(path.join(root, INTRO_FILE), 'utf8')
  return new Map([
    ['docs/guidelines/rules-index.md', renderIndex({ sources, declarations })],
    ['docs/guidelines/enforcement.md', renderEnforcement({ intro, sources, declarations, notes: readNotes(root), tools: readTools(root) })],
  ])
}

/** The generated files whose content on disk differs from what they should be. */
export function findStaleFiles(root) {
  return [...renderAll(root)]
    .filter(([file, content]) => {
      const full = path.join(root, file)
      return !existsSync(full) || readFileSync(full, 'utf8') !== content
    })
    .map(([file]) => file)
}

function main() {
  if (process.argv.includes('--check')) {
    const stale = findStaleFiles(ROOT)
    if (stale.length === 0) return 0
    console.error(`generate-guidelines: out of date: ${stale.join(', ')}. Run: node scripts/generate-guidelines.mjs`)
    return 1
  }
  for (const [file, content] of renderAll(ROOT)) {
    writeFileSync(path.join(ROOT, file), content)
    console.log(`wrote ${file}`)
  }
  return 0
}

const entry = process.argv[1]
if (entry && path.resolve(entry) === fileURLToPath(import.meta.url)) process.exitCode = main()
